// Author: MiYu. Real JASS save lookup uses the isolated War3 user directory.
#include "session.h"
#include "setup.h"
#include <fstream>
#include <iostream>
using namespace war3;
int wmain(int argc,wchar_t** argv){try{
    if(argc!=4)throw std::runtime_error("Usage: war3_save_exists_tests <data-root> <map> <scratch-root>");auto root=fs::absolute(argv[3])/std::to_wstring(GetCurrentProcessId());if(fs::exists(root))throw std::runtime_error("Scratch directory already exists");if(!SetEnvironmentVariableW(L"MEGINE_WAR3_USER_DIR",root.c_str()))throw std::runtime_error("Cannot set isolated user directory");Archives archives(argv[1]);archives.mountMap(argv[2]);auto world=World::read(archives);auto info=world->data().info;ScriptSession session(jass::Module::compile(jass::Program::read(archives)),info);session.attachWorld(std::move(world));session.audioMuted(true);session.audioSimulationClock();session.configure();PlayerSetup setup(info,session.config());session.applySetup(setup);session.startMain();auto& vm=session.runtime();auto exists=[&](std::string name){return vm.invoke("SaveGameExists",std::array{vm.string(name)}).bits!=0;};auto require=[](bool value,const char* message){if(!value)throw std::runtime_error(message);};require(!exists("Blizzard\\Zones\\OrcX01.w3z"),"Missing save reported present");auto dir=root/L"Saves"/L"Blizzard"/L"Zones";fs::create_directories(dir);std::ofstream file(dir/L"OrcX01.w3z",std::ios::binary);file<<"test-save";file.close();require(bool(file),"Could not create isolated save");require(exists("Blizzard\\Zones\\OrcX01.w3z"),"Existing save not found");require(exists("blizzard/zones/orcx01.w3z"),"Windows case or separator lookup differs");require(!exists("Blizzard\\Zones") && !exists("..\\OrcX01.w3z") && !exists("C:\\OrcX01.w3z"),"Invalid save name was accepted");auto copy=[&](std::string from,std::string to){return vm.invoke("CopySaveGameBJ",std::array{vm.string(from),vm.string(to)}).bits!=0;};auto saved=std::string("Blizzard\\Zones\\OrcX01.w3z"),backup=std::string("Blizzard\\Slot1\\OrcX01.w3z");require(copy(saved,backup) && exists(backup),"Save copy did not create destination");auto read=[&](const fs::path& path){std::ifstream input(path,std::ios::binary);return std::string(std::istreambuf_iterator<char>(input),{});};auto backupFile=root/L"Saves"/L"Blizzard"/L"Slot1"/L"OrcX01.w3z";require(read(backupFile)=="test-save","Copied save bytes differ");{std::ofstream replace(backupFile,std::ios::binary|std::ios::trunc);replace<<"old";}require(copy(saved,backup) && read(backupFile)=="test-save","Save overwrite did not replace contents");require(!copy("Blizzard\\Zones\\missing.w3z",backup) && read(backupFile)=="test-save","Missing source changed destination");require(!copy(saved,"..\\escape.w3z") && !copy(saved,saved) && !exists("Blizzard\\Zones\\NUL.w3z") && !exists(".. \\OrcX01.w3z"),"Unsafe save copy path accepted");auto remove=[&](std::string name){return vm.invoke("RemoveSaveDirectoryBJ",std::array{vm.string(name)}).bits!=0;};require(!remove("") && !remove("..\\..") && !remove("Blizzard\\missing") && exists(backup),"Unsafe or missing save directory removed");auto nested=dir/L"nested";fs::create_directories(nested);{std::ofstream nestedFile(nested/L"zone.w3z",std::ios::binary);nestedFile<<"zone";}auto outside=root/L"outside";fs::create_directories(outside);{std::ofstream marker(outside/L"keep.txt",std::ios::binary);marker<<"keep";}auto link=dir/L"link";if(CreateSymbolicLinkW(link.c_str(),outside.c_str(),SYMBOLIC_LINK_FLAG_DIRECTORY|0x2)){require(!remove("Blizzard\\Zones") && exists(saved) && fs::exists(outside/L"keep.txt"),"Save removal followed a directory link");require(RemoveDirectoryW(link.c_str())!=0,"Could not remove isolated link");std::cout<<"PASS directory link rejection\n";}else std::cout<<"SKIP directory link creation\n";require(remove("Blizzard\\Zones") && !fs::exists(dir) && exists(backup) && fs::exists(outside/L"keep.txt"),"Save directory removal affected wrong files");require(!GetModuleHandleW(L"Game.dll"),"Game.dll loaded");std::cout<<"PASS save lookup, copy and directory removal\nRESULT passed=1 failed=0 game_dll_loaded=false\n";return 0;
}catch(const std::exception& e){std::cerr<<"error="<<e.what()<<'\n';return 1;}}
